import * as THREE from './three.module.js';
const host=document.querySelector('#scene'), dialog=document.querySelector('#letter');
document.querySelector('#open').onclick=()=>{dialog.showModal();burst=1;};document.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.querySelector('#share').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);const t=document.createElement('div');t.className='toast';t.textContent='Đã sao chép liên kết thiệp ♡';document.body.append(t);setTimeout(()=>t.remove(),2500);}catch{document.querySelector('#share').textContent='Bạn có thể sao chép địa chỉ trên trình duyệt';}};
let burst=0;
try{
const scene=new THREE.Scene(), camera=new THREE.PerspectiveCamera(33,innerWidth/innerHeight,.1,100);camera.position.set(0,0,15);
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setClearColor(0,0);host.appendChild(renderer.domElement);renderer.outputColorSpace=THREE.SRGBColorSpace;
scene.add(new THREE.HemisphereLight(0xfff8ee,0x987a83,3));const light=new THREE.DirectionalLight(0xffeee5,4);light.position.set(-3,6,8);scene.add(light);const fill=new THREE.DirectionalLight(0xffc7d5,2);fill.position.set(5,0,3);scene.add(fill);
const bouquet=new THREE.Group();scene.add(bouquet);const pinks=[0xc9768e,0xe39caf,0xd98ca3,0xf0b6c4,0xb95c78];const stemMat=new THREE.MeshStandardMaterial({color:0x74846b,roughness:.9});const leafMat=new THREE.MeshStandardMaterial({color:0x7e8c72,side:THREE.DoubleSide,roughness:.8});
function tube(a,b,r,mat){const d=new THREE.Vector3().subVectors(b,a),m=new THREE.Mesh(new THREE.CylinderGeometry(r,r*.8,d.length(),8),mat);m.position.copy(a).add(b).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());return m;}
function leaf(x,y,z,angle,s){const mesh=new THREE.Mesh(new THREE.SphereGeometry(1,16,12),leafMat);mesh.scale.set(.2*s,.58*s,.035);mesh.position.set(x,y,z);mesh.rotation.z=angle;mesh.rotation.y=.4;bouquet.add(mesh);}
const positions=[[-1.1,1.05,0],[.1,1.6,-.25],[1.1,1.1,-.1],[-.55,.45,.7],[.7,.45,.8],[-1.55,.15,-.3],[1.5,.05,-.35],[.1,-.05,1]];
positions.forEach(([x,y,z],idx)=>{bouquet.add(tube(new THREE.Vector3(0,-2.6,0),new THREE.Vector3(x,y,z),.025,stemMat));const flower=new THREE.Group();flower.position.set(x,y,z);flower.rotation.set(.25+(idx%3)*.12,(idx-4)*.1,idx*.8);const material=new THREE.MeshStandardMaterial({color:pinks[idx%5],roughness:.65,side:THREE.DoubleSide});for(let layer=0;layer<4;layer++){const count=layer===0?5:7;for(let j=0;j<count;j++){const angle=j/count*Math.PI*2+layer*.55;const rad=.08+layer*.105;const petal=new THREE.Mesh(new THREE.SphereGeometry(1,20,14),material);petal.scale.set(.16+layer*.045,.22+layer*.035,.055);petal.position.set(Math.cos(angle)*rad,Math.sin(angle)*rad,.22-layer*.075);petal.rotation.set(Math.sin(angle)*.55,-Math.cos(angle)*.55,angle-Math.PI/2);flower.add(petal);}}bouquet.add(flower);});
for(let i=0;i<14;i++){const side=i%2?1:-1;const y=-1.9+i*.23;leaf(side*(.3+(i%4)*.35),y,-.3,side*(-.55-(i%3)*.25),.65+(i%3)*.15);}
const ribbonMat=new THREE.MeshStandardMaterial({color:0xd5a1a9,roughness:.5,metalness:.1});for(const side of [-1,1]){const loop=new THREE.Mesh(new THREE.TorusGeometry(.32,.065,8,40),ribbonMat);loop.scale.set(1.3,.65,1);loop.position.set(side*.35,-1.7,.38);loop.rotation.z=side*.4;bouquet.add(loop);const tail=new THREE.Mesh(new THREE.PlaneGeometry(.19,.9),ribbonMat);tail.position.set(side*.2,-2.12,.35);tail.rotation.z=side*.24;bouquet.add(tail);}
const dustGeometry=new THREE.BufferGeometry(),coords=new Float32Array(210);for(let i=0;i<210;i++)coords[i]=(Math.random()-.5)*15;dustGeometry.setAttribute('position',new THREE.BufferAttribute(coords,3));const dust=new THREE.Points(dustGeometry,new THREE.PointsMaterial({color:0xc58b83,size:.035,transparent:true,opacity:.5}));scene.add(dust);
let px=0,py=0;addEventListener('pointermove',e=>{px=(e.clientX/innerWidth-.5);py=(e.clientY/innerHeight-.5);});
function resize(){const w=host.clientWidth,h=host.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();if(w<700){bouquet.position.set(0,-2.45,0);bouquet.scale.setScalar(.95);camera.position.z=16;}else{bouquet.position.set(3.05,-.05,0);bouquet.scale.setScalar(1.2);camera.position.z=15;}}addEventListener('resize',resize);resize();const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;renderer.setAnimationLoop(t=>{if(!reduced){bouquet.rotation.y=Math.sin(t*.0003)*.12+px*.13;bouquet.rotation.z=Math.sin(t*.0004)*.025;bouquet.rotation.x=py*.07;dust.rotation.y=t*.000015;if(burst>0){dust.rotation.z+=.008*burst;burst*=.98;}}renderer.render(scene,camera);});
}catch(e){host.innerHTML='<div style="position:absolute;right:12%;top:55%;font-size:100px" aria-label="Bó hoa">💐</div>';console.error(e);}
